<?php $pageTitle = 'Owner setup'; ?>
<section class="auth-wrap"><div class="auth-aside"><span class="eyebrow">One-time owner setup</span><h1>Secure the owner account.</h1><p>Owner setup locks permanently after the first owner account is created. The password is stored as a secure hash.</p></div><form class="auth-form" method="post" action="<?= rc_e(rc_endpoint()) ?>"><?= rc_csrf_field() ?><input type="hidden" name="action" value="install-admin"><h2>Create owner account</h2><?php if (empty($setupConfigured)): ?><p class="flash flash-error">Owner setup is unavailable until the RIZ_OWNER_SETUP_KEY environment variable is configured.</p><?php else: ?><div class="field"><label for="setup-key">Master setup credential</label><input id="setup-key" name="setup_key" type="password" autocomplete="off" required></div><div class="field"><label for="name">Full name</label><input id="name" name="full_name" maxlength="120" required></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" maxlength="254" required></div><div class="field"><label for="password">Password</label><input id="password" name="password" type="password" minlength="14" autocomplete="new-password" required><small>At least 14 characters.</small></div><button class="button form-submit" type="submit">Create owner account</button><?php endif; ?></form></section>
